//parse messages and put them in the pyErrorMessage array depending on page name value
//get Parameters

String Message = tools.getParamValue("Message");
String stackTrace=tools.getParamValue("stacktrace");
String currentPageName=tools.getParamValue("pagename");

//check if the Message or stackTrace is blank 
if (Message.trim().length() > 0 || stackTrace.trim().length() > 0)
{ 

//Get the  Properties in the clipboard
ClipboardProperty pyMessages =tools.getStepPage().getProperty(".pyErrors.pyMessages");
int totalPages =pyMessages.size();
int currentIndex=1;

//check if the number of pyMessages pages is Zero
    if(totalPages==0)
     {
        tools.getStepPage().getProperty(".pyErrors.pyMessages(<append>).pyPageName").setValue(currentPageName);
        currentIndex =1;
     }  
     else if(totalPages>=1)
     {
      //check if the page name exists in the pyMessages list and also check if the page name is blank.

       for(int n=1;n<=totalPages;n++)
       {
         String existingPageName =tools.getStepPage().getProperty(".pyErrors.pyMessages("+n+").pyPageName").toString();

	  if(currentPageName.trim().equals(existingPageName.trim()))
	    {
             //get the index value
             currentIndex=n;  
             break;
             }
            else
            {
              if(n==totalPages)
	      {
		tools.getStepPage().getProperty(".pyErrors.pyMessages(<append>).pyPageName").setValue(currentPageName);              
		//add new index.
                  currentIndex=n+1;
	      }
	    } 
       }

     }

//check if stackTrace is blank
if(stackTrace.trim().length() > 0)
{
 tools.getStepPage().getProperty(".pyErrors.pyMessages("+currentIndex+").pyStackTrace").setValue(stackTrace);
}

//check if the Message is blank 
if (Message.trim().length() > 0) 
{
 ClipboardProperty pyErrorMessage = tools.getStepPage().getProperty(".pyErrors.pyMessages("+currentIndex+").pyErrorMessage");
 int ExistingErrorCount = tools.getStepPage().getProperty(".pyErrors.pyMessages("+currentIndex+").pyErrorCount").toInteger();
 int ErrorCount = tools.getParamAsInteger(PropertyInfo.TYPE_INTEGER, "MessageCount");
 if ( ErrorCount == 0)
  ErrorCount = 1;

 int delim = 0;
 for (int idx = 0; idx < ErrorCount; idx++)
 {
  delim = Message.indexOf('\n');
  if (delim > 0)
  {
   pyErrorMessage.add(Message.substring(0,delim));
   Message = Message.substring(delim+1);
  }
  else
  {
   pyErrorMessage.add(Message);
   break;
  }
 }
  ErrorCount += ExistingErrorCount;
  //set values to clipboard.
  tools.getStepPage().getProperty(".pyErrors.pyMessages("+currentIndex+").pyErrorCount").setValue(ErrorCount);
 }
}
